+import { useEffect, useState } from "react";
+import { getUsageSummary, type UsageSummary } from "../../api/usage";
+import { Card } from "../../ui/Card";
+import { Meter } from "../../ui/Meter";
+import { formatCents } from "../../lib/money";
+import "./usage.css";
+
+export function UsageDashboard({ accountId }: { accountId: string }) {
+  const [summary, setSummary] = useState<UsageSummary | null>(null);
+  const [failed, setFailed] = useState(false);
+
+  useEffect(() => {
+    getUsageSummary(accountId)
+      .then(setSummary)
+      .catch(() => setFailed(true));
+  }, [accountId]);
+
+  if (failed) {
+    return <p className="usage-error">We could not load your usage. Try again in a minute.</p>;
+  }
+  if (!summary) {
+    return <p className="usage-loading">Loading usage…</p>;
+  }
+
+  const overLimit = summary.apiCalls > summary.apiCallLimit;
+
+  return (
+    <section className="usage-dashboard">
+      <h1>Usage this billing period</h1>
+      <p className="usage-period">
+        {summary.periodStart} to {summary.periodEnd}
+      </p>
+
+      <div className="usage-grid">
+        <Card title="API calls">
+          <Meter value={summary.apiCalls} max={summary.apiCallLimit} />
+          <p>
+            {summary.apiCalls.toLocaleString()} of {summary.apiCallLimit.toLocaleString()} included
+          </p>
+          {overLimit && (
+            <p className="usage-warning">
+              You are over your plan limit. Extra calls are billed at {formatCents(summary.overageRateCents)} each.
+            </p>
+          )}
+        </Card>
+
+        <Card title="Seats">
+          <Meter value={summary.seatsUsed} max={summary.seatsIncluded} />
+          <p>
+            {summary.seatsUsed} of {summary.seatsIncluded} seats in use
+          </p>
+        </Card>
+
+        <Card title="Projected invoice">
+          <p className="usage-total">{formatCents(summary.projectedInvoiceCents)}</p>
+          <p>Estimate for this period, including overage so far.</p>
+        </Card>
+      </div>
+
+      <a className="usage-upgrade" href="/settings/billing/upgrade">
+        Upgrade plan
+      </a>
+    </section>
+  );
+}
